function esc(s){ return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function faqItems(p){
  const core = [
    [`What is the fastest way to find ${p.angle} in a car deal?`,`Ask for the written out-the-door price and the complete retail installment contract before discussing the monthly payment. Compare the vehicle price, every fee, every optional product, APR, amount financed, term, and total of payments as separate lines.`],
    [`Are dealer add-ons required to get an auto loan?`,`Generally, optional add-ons are not required to obtain dealer financing. Read the product name, price, and acceptance box. If a product is described as required, ask the dealer to identify the lender or legal requirement in writing.`],
    [`Can a dealer change the price after I agree?`,`A dealer should not quietly add charges to a signed agreement. Whether a deal can be changed depends on the documents, state law, and whether financing was final. Never sign a second contract without comparing it line by line to the first.`],
    [`Does a lower monthly payment mean a better deal?`,`No. A lower payment can result from a longer term, a larger down payment, a higher amount financed, or a balloon or deferred-payment feature. Compare APR, amount financed, finance charge, term, and total of payments.`],
    [`How can HiddenFeeAI help with this topic?`,`HiddenFeeAI can compare the vehicle quote, purchase agreement, and financing documents to surface fees, add-ons, renewal or cancellation language, arithmetic mismatches, and terms worth asking about. It is a review aid, not a law firm or lender.`],
    [`What should I do if a fee is not explained?`,`Ask for the fee’s purpose, whether it is required, whether it is negotiable, whether it is taxable, and where it appears in the contract. If the explanation changes, pause and request a corrected written quote.`],
    [`Can I negotiate the APR?`,`Often, yes. A preapproval from a bank or credit union gives you a comparison point. Ask the dealer whether its offer uses the lender’s buy rate or includes a discretionary markup.`],
    [`Should I sign a blank contract?`,`No. Do not sign a contract with blank prices, payment terms, product choices, trade values, or dates. A blank can later be completed in a way you did not intend.`],
    [`What documents should I keep?`,`Keep the buyer’s order, retail installment contract, addendum, warranty or service-contract terms, GAP certificate, trade payoff, odometer disclosure, delivery receipt, and every email or text about the deal.`],
    [`When should I walk away?`,`Walk away when the written numbers do not match the agreement, an optional product is presented as required, the dealer refuses an out-the-door quote, financing is not clearly final, or you are pressured to sign without time to review.`]
  ];
  const extra = [
    ['What is an out-the-door price?','The out-the-door price is the total needed to complete the purchase, including the vehicle price, dealer charges, government charges, taxes, selected add-ons, trade equity, and other amounts shown in the buyer’s order.'],
    ['Are documentation fees always illegal?','No. Documentation fees are regulated differently by state. A fee can be permitted and still be negotiable or economically unattractive. Compare the complete out-the-door total across dealers.'],
    ['Can optional products be canceled?','Some products have cancellation rights or refund formulas, but the rules and deadlines vary by contract and state. Read the product agreement—not just the sales pitch—and request cancellation in writing.'],
    ['What is negative equity?','Negative equity means the trade-in payoff is greater than the trade-in value. The difference can be added to the new loan, increasing the amount financed before any new add-on is included.'],
    ['What is APR?','APR is the annualized cost of credit that incorporates the interest rate and certain finance charges. It is more useful than the payment alone when comparing loan offers.'],
    ['What is a finance charge?','A finance charge is the dollar cost of credit disclosed in the lending documents. It is separate from the amount financed and helps show how much borrowing costs over the term.'],
    ['What is a service contract?','A service contract is a separate agreement promising specified repair coverage for a defined period, subject to exclusions, deductibles, authorization rules, and claim procedures.'],
    ['What is GAP?','GAP is an optional product intended to cover some difference between an auto loan balance and an insurer’s settlement after a covered total loss, subject to its terms and limits.'],
    ['What is dealer-arranged financing?','Dealer-arranged financing is a loan obtained through a dealership from a third-party lender. The dealer may receive compensation and may have discretion over the offered APR.'],
    ['What is conditional delivery?','Conditional delivery means the buyer receives the vehicle before financing or another condition is fully final. The contract language determines what happens if the condition fails.']
  ];
  return [...core,...extra].map((x,i)=>{const pair=Array.isArray(x)?x:[x[0],x[1]]; return `<details ${i===0?'open':''}><summary>${esc(pair[0])}</summary><p>${pair[1]}</p></details>`}).join('');
}

